const setNow=ms=>f.clock.set(ms-Date.now()),nowMs=()=>f.clock.now(),iso=(d=0)=>new Date(nowMs()+d).toISOString();
const kstDay=(d=0)=>new Date(nowMs()+9*HOUR+d).toISOString().slice(0,10);
