const factPost=async(s,input)=>{
 sql.prepare("DELETE FROM records WHERE kind='execution_rate'").run();
 const res=await factsRoute.POST(new Request('https://agency.test/api/brand-facts',{method:'POST',headers:{'content-type':'application/json',...headersOf(s)},body:JSON.stringify(input)}));
 const text=await res.text(),body=JSON.parse(text);responses.push(body);return {status:res.status,body,text};
};
const snapshot=()=>sql.prepare("SELECT id,data FROM records WHERE kind LIKE 'recruitment_%' OR kind='franchise_audit' ORDER BY id").all().map(r=>r.id+'\t'+r.data).join('\n');
const assetKey=(id,v)=>`${WS}:recruitment_asset:${id}:${v}`;
const assetRows=id=>sql.prepare("SELECT id,parent_id,data FROM records WHERE kind='recruitment_asset' AND json_extract(data,'$.id')=? ORDER BY json_extract(data,'$.version')").all(id).map(r=>({key:r.id,parent:r.parent_id,...JSON.parse(r.data)}));
const assetRow=(id,v)=>JSON.parse(sql.prepare("SELECT data FROM records WHERE kind='recruitment_asset' AND id=?").get(assetKey(id,v)).data);
const eventRow=id=>JSON.parse(sql.prepare("SELECT data FROM records WHERE kind='recruitment_event' AND id=?").get(`${WS}:recruitment_event:${id}`).data);
