const saveFact=async d=>{const r=await factPost(boss,{action:'save_fact',data:d,confirmed:true});assert.equal(r.status,200,JSON.stringify(r.body));return r.body};
const fact=(brandId,x)=>({brandId,status:'confirmed',source:'가상 정보공개서',verifiedAt:VERIFIED,...x});
const TOTAL_DATA=fact('fr-a',{key:'startup_cost_total',value:'4,500만원',validUntil:UNTIL_Q,sourceRef:{disclosureVersionId:dvA,fiscalYear:2025,page:12},cost:{storeType:'소형 매장',includes:['가맹비','교육비','인테리어'],excludes:['임차보증금','권리금'],areaM2:33}});
