const B_COUNT=await saveFact(fact('fr-b',{key:'franchise_store_count',value:'40개',validUntil:UNTIL_Y,sourceRef:{disclosureVersionId:dvB,fiscalYear:2025,page:3,asOf:'2025-12-31'}}));
await server.recordStatement(WS,'store','st-a',{id:'st-a',brandId:'fr-a',name:'가상 지점'},'fr-a').run();
