const campaign=(id,brandId,objective,title)=>server.recordStatement(WS,'campaign',id,{id,brandId,title,goal:'가상 목표',audience:'',channels:'',stores:'',products:'',budget:null,startDate:'',endDate:'',constraints:'',sources:'',status:'approved',version:1,createdAt:'2026-10-01T00:00:00.000Z',updatedAt:'2026-10-01T00:00:00.000Z',...(objective?{objective}:{})}).run();
for(const [id,b,o,t] of [['ca-a','fr-a','franchise_recruitment','가상 가맹 모집 A'],['ca-a2','fr-a','franchise_recruitment','가상 가맹 모집 A2'],['ca-cons','fr-a',null,'가상 소비자 캠페인'],['ca-b','fr-b','franchise_recruitment','가상 가맹 모집 B'],['ca-c','fr-c','franchise_recruitment','가상 가맹 모집 C'],['ca-l','fr-l','franchise_recruitment','가상 가맹 모집 L']])await campaign(id,b,o,t);
