check('I45: the startup page template carries the cost fact line and its footnote, and the template refs are the cost fact',r.status===200&&TPL.startup_page.includes(COST_LINE)&&TPL.startup_page.includes(FOOT_A)&&TPL.event_deck.includes(COST_LINE)&&JSON.stringify(TREFS)===JSON.stringify([{id:A_TOTAL.id,version:1}])&&r.body.costFactsMissing===false);
